package com.regional.corebanking.payment.infrastructure.amplitude; import org.junit.jupiter.api.Test; import java.sql.*; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*; class PaymentExecutionSqlDialectTest { @Test void preservesEvidence(){var d=new InformixPaymentExecutionSqlDialect();assertThat(d.findCustomerOpposition()).contains("bkoppcli");assertThat(d.findAccountOpposition()).contains("bkoppcom");assertThat(d.findOperationOpposition()).contains("bkopl");assertThat(d.findAvailableFunds()).contains("a.sin-nvl(a.minds,0)+nvl(maut,0) as solde");assertThat(d.findAccountingDatePrimary()).contains("mnt2");assertThat(d.findAccountingDateFallback()).contains("mnt1");assertThat(d.findNightMode()).contains("SITE-CENT");} @Test void onlyInformixDirtyRead()throws Exception{Connection c=mock(Connection.class);Statement s=mock(Statement.class);when(c.createStatement()).thenReturn(s);new InformixPaymentExecutionSqlDialect().prepareConnection(c);verify(s).execute("SET ISOLATION TO DIRTY READ");clearInvocations(c,s);new OraclePaymentExecutionSqlDialect().prepareConnection(c);verifyNoInteractions(s);} }
